def setup_checkpoint(args, files):
    """Only called when a checkpoint flag is set; the only place vidx.checkpoint is imported."""
    from vidx import checkpoint

    run_name = args.run_name or Path(args.output).name
    stores = []
    if args.checkpoint_dir:
        stores.append(checkpoint.DirStore(args.checkpoint_dir, run_name))
    if args.checkpoint_hf_repo:
        stores.append(checkpoint.HFStore(args.checkpoint_hf_repo, run_name))
    fp = checkpoint.make_fingerprint(Path(args.input).resolve(), args.limit_videos, args.output, run_name,
                                     config={"sample": args.sample, "precision": args.precision})
    ckpt = checkpoint.Checkpointer(
        stores, args.output, fp, args.checkpoint_minutes, args.dump_frames,
        inputs={f.name: f.stat().st_size for f in files},
    )
    if args.resume:
        log.info("checkpoint: %s", ckpt.restore())
    elif ckpt.has_existing():
        raise checkpoint.CheckpointError(
            f"a checkpoint named {run_name!r} already exists: use --resume, or a different --run-name"
        )
    return ckpt




def gen_name(n):
    return f"gen-{n:04d}"


def make_fingerprint(input_path, limit_videos, output, run_name, config=None):
    """What must be identical for a resume. The parquet files themselves are checked separately
    (Checkpointer.inputs_used), so files added to the input folder later do not matter.
    config: settings that change the results (sampling, precision), so a resume never mixes them. It is
    left out for the brute-force baseline (sample 0, fp32), so checkpoints made before it existed still match."""
    fp = {"input": str(input_path), "limit_videos": limit_videos, "output": Path(output).name, "run_name": run_name}
    if config and config != BASELINE_CONFIG:
        fp["config"] = config
    return json.loads(json.dumps(fp))


class _HashingFile:
    """Write-through file wrapper that counts bytes and hashes them, so nothing is re-read later."""

    def __init__(self, f):
        self.f, self.size, self.sha = f, 0, hashlib.sha256()

    def write(self, data):
        self.sha.update(data)
        self.size += len(data)
